def move_contacts(apps, schema_editor):
    """The single contact fields of an event become the first person(s)."""
    Event = apps.get_model('production', 'Event')
    VenueContact = apps.get_model('production', 'VenueContact')
    for e in Event.objects.all():
        emails = [x.strip() for x in (e.venue_email or '').split(',') if x.strip()]
        if not (e.venue_contact or emails or e.venue_phone):
            continue
        VenueContact.objects.create(id=uuid.uuid4().hex[:24], event=e, role='Contactpersoon', name=e.venue_contact or '',
                                    email=emails[0] if emails else '', phone=e.venue_phone or '', sort=0)
        for i, extra in enumerate(emails[1:], 1):
            VenueContact.objects.create(id=uuid.uuid4().hex[:24], event=e, email=extra, sort=i)


